import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import com.google.common.collect.Lists;

public class ThreadSnapshotParser {

	public List<ThreadSnapshot> parse(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
		List<ThreadSnapshot> snapshots = new ArrayList<ThreadSnapshot>();
		BufferedReader reader = null;
		try {
			reader = new BufferedReader(new FileReader(file));
			String line = null;
			while ((line = reader.readLine()) != null) {
				if (line.isEmpty()) {
					continue;
				}

				ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
				if (snapshot == null) {
					continue;
				}

				long timestamp = snapshot.getTimestamp();
				if (timestamp == -1L) {
					timestamp = Long.parseLong(snapshot.getId().substring(0, snapshot.getId().indexOf('=')));
				}

				if (isInTimeRange(timestamp, timeRanges)) {
					snapshots.add(snapshot);
				}
			}
		} finally {
			if (reader != null) {
				reader.close();
			}
		}

		return snapshots;
	}

	private boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
		for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
			if (timestamp >= timeRange.getStart() && timestamp <= timeRange.getEnd()) {
				return true;
			}
		}
		return false;
	}
}

